// Normalize the enquiry payload coming from the CIC website afterChange hook.
// The webhook delivers the JSON body under $json.body (fallback: $json).
const input = $input.first().json;
const b = input.body || input;

// --- Shared-secret gate: must equal the site's N8N_WEBHOOK_SECRET ---
// Edit EXPECTED_SECRET to enforce; leave the placeholder to skip (dev/test).
const EXPECTED_SECRET = 'REPLACE_WITH_WEBHOOK_SECRET';
const headers = input.headers || {};
const provided = headers['x-n8n-secret'] || headers['X-N8N-Secret'] || '';
if (EXPECTED_SECRET !== 'REPLACE_WITH_WEBHOOK_SECRET' && provided !== EXPECTED_SECRET) {
  throw new Error('Unauthorized: bad or missing x-n8n-secret header');
}

// --- Phone -> E.164 digits for WhatsApp Cloud API (no leading '+') ---
const raw = String(b.phone || '').replace(/\D/g, '');
let waNumber = '';
if (raw) {
  if (raw.startsWith('995')) {
    waNumber = raw;                 // already has Georgian country code
  } else if (raw.length === 9 && raw.startsWith('5')) {
    waNumber = '995' + raw;         // local mobile, e.g. 5XX XXX XXX
  } else if (raw.length > 9) {
    waNumber = raw;                 // looks like it already carries a country code
  } else {
    waNumber = '995' + raw;         // best-effort: assume Georgia
  }
}

// --- Message language artefacts, matched to the submission locale ---
const isEn = String(b.locale || 'ka') === 'en';
const templateName = isEn ? 'enquiry_ack_en' : 'enquiry_ack_ka';
const langCode = isEn ? 'en_US' : 'ka';
const name = b.name || '';
// Plain-text reference of the acknowledgement (the real send uses the approved template):
const bodyText = isEn
  ? `Hello ${name}, thank you for contacting One World. Our team will reach out to you shortly.`
  : `გამარჯობა ${name}, მადლობა One World-თან დაკავშირებისთვის. ჩვენი გუნდი მალე დაგიკავშირდებათ.`;

return [{
  json: {
    name,
    email: b.email || '',
    phone: b.phone || '',
    waNumber,
    fieldOfInterest: b.fieldTitle || b.fieldOfInterest || '',
    studyLevel: b.studyLevel || '',
    preferredContact: b.preferredContact || '',
    message: b.message || '',
    source: b.source || '',
    locale: b.locale || 'ka',
    createdAt: b.createdAt || '',
    id: b.id || '',
    templateName,
    langCode,
    bodyText
  }
}];
